package com.example.applenotes.proto

/*
 * Test fixtures shared by :core's tests and :app's unit tests
 * (java-test-fixtures; :app uses testImplementation(testFixtures(project(":core")))).
 * The invariant checker itself is main code: TopotextInvariants.
 */

/**
 * Builders for SYNTHETIC fixtures. Everything here is generated by our own
 * code (NoteCreator + edits) or hand-assembled from the field layout in
 * docs/protocol.md — none of it was captured from iCloud. The only real Apple-written
 * fixture is `fmt-baseline-1.proto` (a Mac-created note).
 */
object Fx {
    fun varint(n: Int, v: Long) = ProtobufWire.encodeVarintField(n, v)
    fun bytes(n: Int, b: ByteArray) = ProtobufWire.Field(n, ProtobufWire.WIRE_LENGTH_DELIM, b)
    fun str(n: Int, s: String) = ProtobufWire.encodeString(n, s)
    fun msg(n: Int, vararg f: ProtobufWire.Field) = bytes(n, ProtobufWire.encode(f.toList()))

    /** An AttributeRun payload: length + arbitrary other fields. */
    fun run(length: Int, vararg f: ProtobufWire.Field): ByteArray =
        ProtobufWire.encode(listOf(varint(1, length.toLong())) + f.toList())

    fun style(code: Int, vararg extra: ProtobufWire.Field) = msg(2, varint(1, code.toLong()), varint(2, 4), *extra)

    fun checklist(uuid: ByteArray, done: Boolean) = msg(5, bytes(1, uuid), varint(2, if (done) 1 else 0))

    fun attachment(id: String, uti: String = "com.apple.notes.table") = msg(12, str(1, id), str(2, uti))

    /** Rewrite the topotext.String fields of a body proto. */
    fun mapString(bytes: ByteArray, f: (List<ProtobufWire.Field>) -> List<ProtobufWire.Field>): ByteArray =
        mapVersion(bytes) { vf ->
            vf.map {
                if (it.fieldNumber == 3 && it.wireType == ProtobufWire.WIRE_LENGTH_DELIM) {
                    it.copy(payload = ProtobufWire.encode(f(ProtobufWire.decode(it.payload))))
                } else it
            }
        }

    fun mapVersion(bytes: ByteArray, f: (List<ProtobufWire.Field>) -> List<ProtobufWire.Field>): ByteArray =
        ProtobufWire.encode(ProtobufWire.decode(bytes).map {
            if (it.fieldNumber == 2 && it.wireType == ProtobufWire.WIRE_LENGTH_DELIM) {
                it.copy(payload = ProtobufWire.encode(f(ProtobufWire.decode(it.payload))))
            } else it
        })

    /** Replace all attribute runs with [runs] (placed where the first run was, or at the end). */
    fun withRuns(bytes: ByteArray, runs: List<ByteArray>): ByteArray = mapString(bytes) { sf ->
        val out = ArrayList<ProtobufWire.Field>()
        var placed = false
        for (f in sf) {
            if (f.fieldNumber == 5) {
                if (!placed) { runs.forEach { out.add(bytes(5, it)) }; placed = true }
                continue
            }
            out.add(f)
        }
        if (!placed) runs.forEach { out.add(bytes(5, it)) }
        out
    }

    fun create(text: String, uuid: ByteArray = testUuid(0)): ByteArray =
        NoteCreator.buildEmptyNoteBytes(uuid, text)

    fun spans(bytes: ByteArray) = NoteBodyEditor.parseAttributeRuns(bytes)

    fun perChar(bytes: ByteArray): Array<NoteBodyEditor.AttrSpan> {
        val text = NoteBodyEditor.readVisibleText(bytes)!!
        return NoteBodyEditor.expandSpansToChars(text, spans(bytes))
    }

    /** The raw AttributeRun payload covering each visible char (length field stripped). */
    fun runBytesPerChar(bytes: ByteArray): List<String> {
        val d = TopotextInvariants.parse(bytes)
        val out = ArrayList<String>()
        for (r in d.runs) {
            val noLen = ProtobufWire.encode(r.fields.filter { it.fieldNumber != 1 })
            repeat(r.length) { out.add(TopotextInvariants.hex(noLen)) }
        }
        return out
    }
}

/** Deterministic replica UUIDs (RFC 4122 v4 shaped) for tests. */
fun testUuid(seed: Int): ByteArray {
    val r = java.util.Random(seed.toLong() * 7919 + 17)
    val b = ByteArray(16).also { r.nextBytes(it) }
    b[6] = ((b[6].toInt() and 0x0F) or 0x40).toByte()
    b[8] = ((b[8].toInt() and 0x3F) or 0x80).toByte()
    return b
}

fun loadFixture(name: String): ByteArray =
    Fx::class.java.classLoader!!.getResourceAsStream(name)!!.readBytes()
